args.TargetContent:
"        function submitTrainingTableConfig() {
            const asset = activeAsset;
            const base = document.getElementById('train-table-base').value;
            const prices = document.getElementById('train-table-prices').value;
            const price_col = document.getElementById('train-table-price-col').value;
            const delay = parseInt(document.getElementById('train-table-delay').value) || 0;
            const out = document.getElementById('train-table-out').value;
            const horizon_ms = parseInt(document.getElementById('train-table-horizon-ms').value) || 14400000;
            const returns = document.getElementById('train-table-returns').value;
            const sources = document.getElementById('train-table-sources').value;

            const params = {
                base: base,
                prices: prices,
                price_col: price_col,
                decision_delay_ms: delay,
                out: out,
                label_horizon_ms: horizon_ms,
                label_returns: returns
            };

            if (sources && sources.trim()) {
                params.sources = sources;
            }

            // Save to localStorage for dynamic telemetry tracking
            try {
                localStorage.setItem('rivenquant_config_train_table_' + asset, JSON.stringify(params));
            } catch (e) {
                console.error("Error saving train table params:", e);
            }

            closeTrainingTableConfig();

            runQuickAction('run_job', {
                job: 'run_training_table',
                params: params
            });
        }"
